def routes(n):
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        if i % 3 == 0:
            continue
        ways[i] = ways[i - 1]
        if i >= 2:
            ways[i] += ways[i - 2]
    return ways[n]

